def profile_list():
    """List cached model profiles."""
    from .profiles import ProfileCache
    cache = ProfileCache()
    for p in cache.list_profiles():
        inv = " (invariant)" if p.is_invariant else ""
        click.echo(f"  {p.model_name}: spread={p.spread_pp:.1f}pp best={p.best_register}{inv}")
        for tp in p.by_task:
            click.echo(f"    {tp.task_type}: best={tp.best_register} spread={tp.spread_pp:.1f}pp")

def _score(self, text: str) -> _FeatureScores:
    lower = text.lower()
    scores = _FeatureScores()

    for pattern, weight in CASUAL_MARKERS:
        if re.search(pattern, lower, re.IGNORECASE):
            scores.casual += weight

    for pattern, weight in TECHNICAL_MARKERS:
        if re.search(pattern, lower, re.IGNORECASE):
            scores.technical += weight

    for pattern, weight in ACADEMIC_MARKERS:
        if re.search(pattern, lower, re.IGNORECASE):
            scores.academic += weight

    for pattern, weight in NARRATIVE_MARKERS:
        if re.search(pattern, lower, re.IGNORECASE):
            scores.narrative += weight

    # Direct heuristic: short text with no strong markers
    words = text.split()
    if len(words) <= 12:
        scores.direct += 1.5
    if len(words) <= 6:
        scores.direct += 1.5

    # Penalize direct if other scores are high
    max_other = max(scores.casual, scores.technical, scores.academic, scores.narrative)
    if max_other > 2.0:
        scores.direct *= 0.3

    return scores

def is_available() -> bool:
    global _checked
    if _checked:
        return _store is not None
    _checked = True
    return _init_store()

def close() -> None:
    global _store, _checked
    if _store is not None:
        _store.close()
    _store = None
    _checked = False

def main():
    """MCP server entry point."""
    try:
        from mcp.server.fastmcp import FastMCP
    except ImportError:
        import sys
        print("MCP server requires: pip install 'transmogrifier[mcp]'", file=sys.stderr)
        sys.exit(1)

    mcp = FastMCP(
        "transmogrifier",
        instructions=(
            "Transmogrifier normalizes linguistic register for better LLM output. "
            "Use transmog_translate before sending prompts to register-sensitive models. "
            "Use transmog_detect to classify input register."
        ),
    )

    from .core import Transmogrifier, TranslationConfig, Register

    _t = Transmogrifier()

    @mcp.tool()
    def transmog_translate(text: str, model: str = "", target_register: str = "") -> dict:
        """Translate text to optimal register for the target model."""
        config = TranslationConfig()
        if target_register:
            config.target_register = Register(target_register)
        result = _t.translate(text, model=model, config=config)
        return result.model_dump()

    @mcp.tool()
    def transmog_detect(text: str) -> dict:
        """Detect the register of input text."""
        reg, conf = _t._detector.detect(text)
        return {"register": reg.value, "confidence": conf}

    @mcp.tool()
    def transmog_profiles() -> list[dict]:
        """List all cached model register sensitivity profiles."""
        return [p.model_dump() for p in _t._profile_cache.list_profiles()]

    mcp.run(transport="stdio")

def transmog_translate(text: str, model: str = "", target_register: str = "") -> dict:
    """Translate text to optimal register for the target model."""
    config = TranslationConfig()
    if target_register:
        config.target_register = Register(target_register)
    result = _t.translate(text, model=model, config=config)
    return result.model_dump()

def transmog_detect(text: str) -> dict:
    """Detect the register of input text."""
    reg, conf = _t._detector.detect(text)
    return {"register": reg.value, "confidence": conf}

def transmog_profiles() -> list[dict]:
    """List all cached model register sensitivity profiles."""
    return [p.model_dump() for p in _t._profile_cache.list_profiles()]

def best_register(self) -> str:
    if not self.accuracies:
        return "direct"
    return max(self.accuracies, key=lambda a: a.accuracy).register

def spread_pp(self) -> float:
    if not self.accuracies:
        return 0.0
    accs = [a.accuracy for a in self.accuracies]
    return (max(accs) - min(accs)) * 100

def spread_pp(self) -> float:
    if not self.accuracies:
        return 0.0
    accs = [a.accuracy for a in self.accuracies]
    return (max(accs) - min(accs)) * 100

def best_register(self) -> str:
    if not self.accuracies:
        return "direct"
    return max(self.accuracies, key=lambda a: a.accuracy).register

def worst_register(self) -> str:
    if not self.accuracies:
        return "direct"
    return min(self.accuracies, key=lambda a: a.accuracy).register

def best_register_for_task(self, task_type: str) -> str:
    """Get optimal register for a specific task type.

    Falls back to aggregate best_register if no per-task data.
    """
    for tp in self.by_task:
        if tp.task_type == task_type:
            return tp.best_register
    return self.best_register

def spread_for_task(self, task_type: str) -> float:
    """Get register spread for a specific task type."""
    for tp in self.by_task:
        if tp.task_type == task_type:
            return tp.spread_pp
    return self.spread_pp

def is_expired(self) -> bool:
    if not self.calibrated_at:
        return False
    try:
        cal = datetime.fromisoformat(self.calibrated_at)
        if cal.tzinfo is None:
            cal = cal.replace(tzinfo=timezone.utc)
        now = datetime.now(timezone.utc)
        hours = (now - cal).total_seconds() / 3600
        return hours > self.ttl_hours
    except (ValueError, TypeError):
        return False

def __init__(self, cache_dir: Path | None = None) -> None:
    self._cache_dir = cache_dir or Path.home() / ".transmogrifier" / "profiles"
    self._memory: dict[str, ModelProfile] = {}

def get(self, model_name: str) -> ModelProfile | None:
    canonical = _ALIASES.get(model_name, model_name)

    if canonical in self._memory:
        profile = self._memory[canonical]
        if not profile.is_expired:
            return profile

    # Check file cache
    profile = self._load_file(canonical)
    if profile and not profile.is_expired:
        self._memory[canonical] = profile
        return profile

    # Fall back to pre-seeded
    if canonical in _PRESEEDED:
        return _PRESEEDED[canonical]

    # Try partial match on pre-seeded keys
    for key, profile in _PRESEEDED.items():
        if key in canonical or canonical in key:
            return profile

    return None

def list_profiles(self) -> list[ModelProfile]:
    profiles = list(_PRESEEDED.values())
    if self._cache_dir.exists():
        for f in self._cache_dir.glob("*.json"):
            try:
                data = json.loads(f.read_text())
                p = ModelProfile(**data)
                if not any(ep.model_name == p.model_name for ep in profiles):
                    profiles.append(p)
            except Exception:
                continue
    return profiles

def _load_file(self, model_name: str) -> ModelProfile | None:
    path = self._cache_dir / f"{model_name}.json"
    if not path.exists():
        return None
    try:
        data = json.loads(path.read_text())
        return ModelProfile(**data)
    except Exception as e:
        logger.debug("Failed to load profile %s: %s", path, e)
        return None

def inject_system_prompt(existing_system: str, injection: str) -> str:
    """Prepend a register normalization instruction to an existing system prompt.

    Idempotent: if the injection is already present, returns unchanged.
    """
    if not injection:
        return existing_system
    if not existing_system:
        return injection
    if injection in existing_system:
        return existing_system
    return f"{injection}\n\n{existing_system}"

def classify(self, text: str) -> tuple[TaskType, float]:
    """Returns (task_type, confidence 0-1)."""
    if not text or not text.strip():
        return TaskType.unknown, 0.0

    lower = text.lower()
    scores: dict[TaskType, float] = {tt: 0.0 for tt in TaskType if tt != TaskType.unknown}

    for task_type, markers in _ALL_MARKERS:
        for pattern, weight in markers:
            if re.search(pattern, lower, re.IGNORECASE):
                scores[task_type] += weight

    best_type = max(scores, key=scores.get)
    best_score = scores[best_type]

    if best_score == 0:
        return TaskType.unknown, 0.5

    sorted_scores = sorted(scores.values(), reverse=True)
    second = sorted_scores[1] if len(sorted_scores) > 1 else 0.0
    total = sum(scores.values()) or 1.0
    confidence = min((best_score - second) / total + 0.5, 1.0)

    return best_type, round(confidence, 3)

def __init__(self, model_name: str = "all-MiniLM-L6-v2") -> None:
    self._model_name = model_name
    self._model = None

def _load(self):
    if self._model is not None:
        return
    try:
        from sentence_transformers import SentenceTransformer
        self._model = SentenceTransformer(self._model_name)
    except ImportError:
        logger.warning("sentence-transformers not installed; semantic validation disabled")
        self._model = False

def validate(self, input_text: str, output_text: str) -> float | None:
    self._load()
    if self._model is False:
        return None
    import numpy as np
    embeddings = self._model.encode([input_text, output_text], normalize_embeddings=True)
    return float(np.dot(embeddings[0], embeddings[1]))

def is_valid(self, input_text: str, output_text: str, threshold: float = 0.95) -> bool | None:
    sim = self.validate(input_text, output_text)
    if sim is None:
        return None
    return sim >= threshold

def create_backend(backend: str | None = None, **kwargs) -> Backend:
    """Factory: create backend from env vars or explicit args."""
    import os
    backend = backend or os.environ.get("TRANSMOG_BACKEND", "anthropic")
    if backend == "anthropic":
        from .anthropic import AnthropicBackend
        return AnthropicBackend(**kwargs)
    elif backend == "openai":
        from .openai import OpenAIBackend
        return OpenAIBackend(**kwargs)
    elif backend == "gemini":
        from .gemini import GeminiBackend
        return GeminiBackend(**kwargs)
    raise ValueError(f"Unknown backend: {backend}")

def _ensure_client(self):
    if self._client is None:
        import anthropic
        self._client = anthropic.Anthropic(api_key=self._api_key)

def complete(self, system: str, messages: list[dict], max_tokens: int = 1024) -> str:
    self._ensure_client()
    kwargs = {"model": self._model, "max_tokens": max_tokens, "messages": messages}
    if system:
        kwargs["system"] = system
    response = self._client.messages.create(**kwargs)
    return response.content[0].text

def _ensure_configured(self):
    if not self._configured:
        import google.generativeai as genai
        genai.configure(api_key=self._api_key)
        self._configured = True

def _ensure_client(self):
    if self._client is None:
        import openai
        self._client = openai.OpenAI(api_key=self._api_key)

def complete(self, system: str, messages: list[dict], max_tokens: int = 1024) -> str:
    self._ensure_client()
    msgs = []
    if system:
        msgs.append({"role": "system", "content": system})
    msgs.extend(messages)
    response = self._client.chat.completions.create(
        model=self._model, messages=msgs, max_tokens=max_tokens, temperature=0
    )
    return response.choices[0].message.content
